/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

// Module-level font loading guaranteed to be ready before frame 0
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type LifeBalanceProps = Record<string, any>;

const LifeBalanceBuckets: React.FC<LifeBalanceProps> = ({
  backgroundColor = "#070912",
  transparentBackground = false,
  durationInSeconds = 10,
  title = "HYROX RACE FORMAT",
  description = "8 x 1km runs, each followed by a functional workout station.",
  stationNames = [
    "Ski Erg",
    "Sled Push",
    "Sled Pull",
    "Burpee Broad Jumps",
    "Rowing",
    "Farmers Carry",
    "Sandbag Lunges",
    "Wall Balls",
  ],
  primaryColor = "#00f0ff", // Neon Cyan
  accentColor = "#9d00ff", // Deep Purple
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safety variables for parser
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Calculations
  const c1 = width * 0.18;
  const c2 = width * 0.39;
  const c3 = width * 0.60;
  const c4 = width * 0.82;
  const r1 = height * 0.45;
  const r2 = height * 0.80;

  // Combine segments (the runs) and nodes (the workout stations)
  const stationsData = [
    {
      id: 1,
      name: stationNames[0] || "Ski Erg",
      nodeX: c1,
      nodeY: r1,
      path: `M ${c1 - 220} ${r1} L ${c1} ${r1}`,
      pathLen: 220,
      labelX: c1 - 110,
      labelY: r1 - 15,
    },
    {
      id: 2,
      name: stationNames[1] || "Sled Push",
      nodeX: c2,
      nodeY: r1,
      path: `M ${c1} ${r1} L ${c2} ${r1}`,
      pathLen: c2 - c1,
      labelX: (c1 + c2) / 2,
      labelY: r1 - 15,
    },
    {
      id: 3,
      name: stationNames[2] || "Sled Pull",
      nodeX: c3,
      nodeY: r1,
      path: `M ${c2} ${r1} L ${c3} ${r1}`,
      pathLen: c3 - c2,
      labelX: (c2 + c3) / 2,
      labelY: r1 - 15,
    },
    {
      id: 4,
      name: stationNames[3] || "Burpee Broad Jumps",
      nodeX: c4,
      nodeY: r1,
      path: `M ${c3} ${r1} L ${c4} ${r1}`,
      pathLen: c4 - c3,
      labelX: (c3 + c4) / 2,
      labelY: r1 - 15,
    },
    {
      id: 5,
      name: stationNames[4] || "Rowing",
      nodeX: c4,
      nodeY: r2,
      // Curve down to the second row
      path: `M ${c4} ${r1} C ${c4 + 200} ${r1}, ${c4 + 200} ${r2}, ${c4} ${r2}`,
      pathLen: 800, // Safe approximation for clamp
      labelX: c4 + 115,
      labelY: (r1 + r2) / 2,
    },
    {
      id: 6,
      name: stationNames[5] || "Farmers Carry",
      nodeX: c3,
      nodeY: r2,
      path: `M ${c4} ${r2} L ${c3} ${r2}`,
      pathLen: c4 - c3,
      labelX: (c3 + c4) / 2,
      labelY: r2 - 15,
    },
    {
      id: 7,
      name: stationNames[6] || "Sandbag Lunges",
      nodeX: c2,
      nodeY: r2,
      path: `M ${c3} ${r2} L ${c2} ${r2}`,
      pathLen: c3 - c2,
      labelX: (c2 + c3) / 2,
      labelY: r2 - 15,
    },
    {
      id: 8,
      name: stationNames[7] || "Wall Balls",
      nodeX: c1,
      nodeY: r2,
      path: `M ${c2} ${r2} L ${c1} ${r2}`,
      pathLen: c2 - c1,
      labelX: (c1 + c2) / 2,
      labelY: r2 - 15,
    },
  ];

  // Timing setup
  const introDuration = 30;
  const totalFrames = durationInSeconds * fps;
  // Reserve 45 frames at the end for final rest
  const sequenceFrames = totalFrames - introDuration - 45; 
  const framesPerStep = Math.max(10, Math.floor(sequenceFrames / stationsData.length));

  // Global Intro Animations
  const titleY = spring({ frame, fps, config: { damping: 14 } });
  const titleOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: spaceGroteskFamily,
        backgroundImage: transparentBackground
          ? "none"
          : `radial-gradient(ellipse at 50% -20%, ${accentColor}33 0%, ${backgroundColor} 70%, #030408 100%)`,
        overflow: "hidden",
      }}
    >
      {/* Title Block */}
      <div
        style={{
          position: "absolute",
          top: height * 0.1,
          left: 0,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          opacity: titleOpacity,
          transform: `translateY(${(1 - titleY) * -50}px)`,
        }}
      >
        <h1
          style={{
            color: "#ffffff",
            fontSize: 64,
            fontWeight: 800,
            margin: 0,
            letterSpacing: "0.05em",
            textShadow: `0px 0px 20px ${primaryColor}66`,
          }}
        >
          {title}
        </h1>
        <p
          style={{
            color: "#a0a5b5",
            fontSize: 28,
            fontWeight: 400,
            marginTop: 16,
            maxWidth: width * 0.6,
            textAlign: "center",
          }}
        >
          {description}
        </p>
      </div>

      <svg
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          overflow: "visible",
        }}
      >
        <defs>
          <filter id="neonGlow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="6" result="coloredBlur" />
            <feMerge>
              <feMergeNode in="coloredBlur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>

        {/* Draw Sequence */}
        {stationsData.map((station, i) => {
          const stepStartFrame = introDuration + i * framesPerStep;
          const drawDuration = framesPerStep * 0.7;
          const nodeStartFrame = stepStartFrame + drawDuration;

          // Connecting Line (1km run)
          const lineProgress = interpolate(
            frame,
            [stepStartFrame, stepStartFrame + drawDuration],
            [station.pathLen, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // "1km Run" Label Fade
          const runLabelOpacity = interpolate(
            frame,
            [stepStartFrame + drawDuration * 0.3, stepStartFrame + drawDuration],
            [0, 0.9],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Node Scale Spring
          const nodeScale = spring({
            frame: frame - nodeStartFrame,
            fps,
            config: { damping: 14, mass: 0.8 },
          });

          // Outer pulsing ring around the node
          const ringPulse = interpolate(
            frame - nodeStartFrame,
            [0, 30, 60],
            [0.8, 1.2, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );
          const ringOpacity = interpolate(
            frame - nodeStartFrame,
            [0, 30, 60],
            [0, 0.4, 0.2],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <g key={`station-group-${station.id}`}>
              {/* Animated Run Path */}
              <path
                d={station.path}
                fill="none"
                stroke={primaryColor}
                strokeWidth={4}
                strokeDasharray={station.pathLen + 10}
                strokeDashoffset={lineProgress}
                strokeLinecap="round"
                filter="url(#neonGlow)"
                style={{ transition: "none" }}
              />

              {/* 1km Run Label */}
              <text
                x={station.labelX}
                y={station.labelY}
                fill={primaryColor}
                fontSize={16}
                fontWeight={600}
                textAnchor="middle"
                letterSpacing="0.1em"
                opacity={runLabelOpacity}
                style={{ transition: "none" }}
              >
                1KM RUN
              </text>

              {/* Workout Station Node */}
              <g
                transform={`translate(${station.nodeX}, ${station.nodeY}) scale(${nodeScale})`}
                style={{ transition: "none" }}
              >
                {/* Decorative Outer Ring */}
                <circle
                  r={48 * ringPulse}
                  fill="none"
                  stroke={accentColor}
                  strokeWidth={2}
                  strokeDasharray="4 6"
                  opacity={ringOpacity}
                />
                
                {/* Main Station Circle */}
                <circle
                  r={36}
                  fill="#0A0D18"
                  stroke={primaryColor}
                  strokeWidth={3}
                  filter="url(#neonGlow)"
                />

                {/* Station Number inside Circle */}
                <text
                  x={0}
                  y={8}
                  fill="#ffffff"
                  fontSize={26}
                  fontWeight={700}
                  textAnchor="middle"
                >
                  {station.id}
                </text>

                {/* Station Name Label */}
                <text
                  x={0}
                  y={75}
                  fill="#ffffff"
                  fontSize={20}
                  fontWeight={600}
                  textAnchor="middle"
                  letterSpacing="0.03em"
                  opacity={0.9}
                  style={{ textShadow: `0px 4px 10px rgba(0,0,0,0.8)` }}
                >
                  {station.name}
                </text>
              </g>
            </g>
          );
        })}
      </svg>
    </AbsoluteFill>
  );
};

export default LifeBalanceBuckets;